extends Node3D
class_name TranslationCubeDemo

@export var door_width: float = 0.5
@export var door_height: float = 1.0
@export var door_depth: float = 0.04

func _ready() -> void:
	_create_doors()

func _create_doors() -> void:
	var door = Node3D.new()

	# The door panel — a flat BoxMesh
	var panel = MeshInstance3D.new()
	var box = BoxMesh.new()
	box.size = Vector3(door_width, door_height, door_depth)
	panel.mesh = box

	var mat = StandardMaterial3D.new()
	mat.albedo_color = Color(0.8, 0.3, 0.3)  # Red
	panel.material_override = mat
	door.add_child(panel)
	add_child(door)

func _on_door_goal_reached(door_name: String) -> void:
	print("Translation Demo: %s opened!" % door_name)
	_check_both_complete()

func _check_both_complete() -> void:
	if _both_reached:
		return

	var left_done = _left_door.is_goal_reached()
	var right_done = _right_door.is_goal_reached()

	if left_done and right_done:
		_both_reached = true
		print("Both doors open! Puzzle complete!")
